import {fixtureEvaluation} from './assessment-core.mjs';
export class SelfEvaluation{
 constructor(h){this.h=h;this.dataset='smoke';this.variant='all';this.tab=new URLSearchParams(location.search).get('selftab')==='protocol'?'protocol':'results';this.plan={model:'',revision:'',dataset:'',split:'',baseline:'固定工作流 + 同一模型',hardware:'',budget:'',threshold:'',seeds:'',notes:''};try{Object.assign(this.plan,JSON.parse(localStorage.getItem('articheck:self-evaluation:plan')||'{}'));}catch{}this.message='';}
 esc(x){return this.h.esc(x);}
 data(){return fixtureEvaluation(this.h.seed.samples);}
 render(){return `<nav class="project-steps" aria-label="系统评估视图">${[['results','结果与逐例'],['protocol','对照实验方案']].map(([k,n])=>`<button data-eval="tab" data-id="${k}" class="${this.tab===k?'active':''}" aria-current="${this.tab===k?'page':'false'}">${n}</button>`).join('')}</nav>${this.tab==='results'?this.results():this.protocol()}`;}
 results(){const d=this.data(),external=this.dataset!=='smoke';const rows=d.rows.filter(r=>this.variant==='all'||r.variant===this.variant),pct=x=>x===null?'—':(100*x).toFixed(1)+'%';return `<div class="evaluation-toolbar"><div class="field"><label for="evaluation-dataset">评测数据</label><select id="evaluation-dataset"><option value="smoke" ${!external?'selected':''}>教学缺陷集 · 已归档</option><option value="core" ${this.dataset==='core'?'selected':''}>CORE-Bench · 尚未接入</option><option value="judge" ${this.dataset==='judge'?'selected':''}>JudgeEval · 尚未接入</option></select></div><button class="btn" data-eval="export">导出当前评估</button></div>${external?`<section class="external-benchmark"><h2>${this.dataset==='core'?'计算复现任务验收':'判定与人工评分一致性'}</h2><p>${this.dataset==='core'?'需要官方任务、执行 harness、固定预算和逐任务结果。':'需要官方 rubric、人工标签及独立判定结果。'}</p><div class="evaluation-missing"><strong>尚无实测结果</strong><span>任务数、成功率、F1 与成本均未填报。</span></div><p>当前接口没有启动这项基准。可先保存对照方案，外部基准成绩须由对应评测器产生。</p><button class="btn" data-eval="tab" data-id="protocol">准备评测方案 →</button></section>`:`<section class="evaluation-source"><div><h2>固定策略在教学缺陷上的判定</h2><p>1 个原创仓库 · ${d.variants} 个受控版本 · ${d.rows.length} 条主张</p><p>数据来源：内置归档报告；真值来自独立的缺陷注入映射。</p></div><span>开发冒烟测试<br>非独立论文测试集</span></section><div class="eval-metrics">${[['宏平均 F1',d.macro_f1.toFixed(3),'问题与正常两类'],['问题召回率',pct(d.recall),`TP ${d.tp} / 正例 ${d.tp+d.fn}`],['正常主张误报率',pct(d.fpr),`FP ${d.fp} / 负例 ${d.rows.filter(r=>!r.label).length}`],['证据不足比例',pct(d.abstention),`${d.abstain} / ${d.rows.length} 条主张`]].map(([n,v,s])=>`<section><h3>${n}</h3><strong>${v}</strong><p>${s}</p></section>`).join('')}</div><div class="evaluation-detail-grid"><section><div class="section-heading"><h2>逐例判定</h2><select id="evaluation-variant" aria-label="筛选教学版本"><option value="all">全部版本</option>${this.h.seed.samples.map(s=>`<option value="${s.sample_id}" ${s.sample_id===this.variant?'selected':''}>${s.sample_id}</option>`).join('')}</select></div><div class="scroll-table"><table class="full-table evaluation-table"><thead><tr><th>版本与主张</th><th>注入真值</th><th>系统判定</th><th>依据</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${this.esc(r.text)}</strong><small>${r.variant} · ${r.claim_id}</small></td><td>${r.label?'有缺陷':'正常'}</td><td>${this.esc({issue:'发现问题',supported:'证据支持',inconclusive:'证据不足'}[r.verdict])}</td><td><details><summary>查看记录</summary><p>${this.esc(r.reason)}</p><code>${this.esc(r.run_id)}</code></details></td></tr>`).join('')}</tbody></table></div></section><aside class="assessment-aside"><h2>结果的适用范围</h2><dl class="evaluation-facts"><div><dt>策略</dt><dd>FixedPlanner + 确定性规则</dd></div><div><dt>真值来源</dt><dd>clean 对照 + 三类单缺陷注入</dd></div><div><dt>划分</dt><dd>开发样例；无独立测试划分</dd></div><div><dt>判定阈值</dt><dd>0.5，规则输出为 0 / 1</dd></div><div><dt>模型训练</dt><dd>本结果未使用训练后的模型</dd></div><div><dt>真实论文任务完成率</dt><dd>未评测</dd></div><div><dt>人工介入与端到端耗时</dt><dd>未记录</dd></div><div><dt>成本与 GPU 用量</dt><dd>未测量</dd></div></dl><p class="small-note">12 条教学主张的零误报不足以证明真实分布的误报率上限。论文复现层级由项目证据单独验收。</p><button class="btn" data-eval="tab" data-id="protocol">设计独立对照 →</button></aside></div>`}`;}
 protocol(){const labels={model:'模型与策略',revision:'模型 / 代码 revision',dataset:'评测数据版本',split:'仓库隔离划分与任务清单',baseline:'对照系统',hardware:'硬件与运行环境',budget:'统一预算与成本口径',threshold:'验证集阈值与冻结规则',seeds:'重复运行与统计方法',notes:'验收与结果归档位置'};return `<div class="assessment-intro"><div><h2>先固定协议，再比较系统</h2><p>这里保存评测方案。尚未执行的实验不进入实测结果。</p></div><button class="btn" data-eval="save">保存方案</button></div>${this.message?`<p class="info-strip" role="status">${this.esc(this.message)}</p>`:''}<div class="plan-layout"><section class="protocol-form">${Object.entries(labels).map(([k,n])=>`<div class="field"><label for="eval-plan-${k}">${n}</label><input id="eval-plan-${k}" data-eval-plan="${k}" value="${this.esc(this.plan[k])}" placeholder="${{model:'例如：固定流程 / SFT Planner / GRPO Planner',revision:'固定版本，确保结果可追溯',dataset:'数据集版本与人工真值来源',split:'同源仓库与变体不能跨训练、验证、测试集',hardware:'相同硬件或披露差异',budget:'输入输出 token、工具时间、GPU 费用及失败任务',threshold:'仅在验证集选阈值，测试集固定',seeds:'随机种子、重复次数、均值与不确定性',notes:'逐任务输出、完整运行日志、聚合脚本'}[k]||''}"></div>`).join('')}</section><aside class="assessment-aside"><h2>两种评估对象</h2><section><h3>复现他人论文</h3><p>材料能否支撑执行，训练和评估是否完成，主要结论是否成立。</p><a class="btn text" href="#projects">打开论文复现工作区 →</a></section><section><h3>评估 ArtiCheck</h3><p>问题召回与误报、任务完成率、人工介入、耗时与成本；与相同条件的策略比较。</p></section><section><h3>发布结果需要的依据</h3><p>固定任务清单与版本、独立真值、逐任务证据、失败与弃权记录、可重复的聚合方式。</p></section></aside></div>`;}
 bind(){document.addEventListener('input',ev=>{if(ev.target.dataset.evalPlan)this.plan[ev.target.dataset.evalPlan]=ev.target.value;});document.addEventListener('change',ev=>{const el=ev.target;if(el.id==='evaluation-dataset'){this.dataset=el.value;this.h.render();}if(el.id==='evaluation-variant'){this.variant=el.value;this.h.render();}if(el.dataset.evalPlan)this.plan[el.dataset.evalPlan]=el.value;});document.addEventListener('click',ev=>{const el=ev.target.closest('[data-eval]');if(!el)return;switch(el.dataset.eval){case'tab':this.tab=el.dataset.id;this.h.render();break;case'save':try{localStorage.setItem('articheck:self-evaluation:plan',JSON.stringify(this.plan));this.message='方案已保存到当前浏览器，尚未启动评测。';}catch{this.message='浏览器保存失败，请导出方案。';}this.h.render();break;case'export':this.h.download('articheck-system-evaluation.json',JSON.stringify({format:'articheck-system-evaluation-v1',dataset:this.dataset,source:this.dataset==='smoke'?'archived_trusted_fixture_runs':'not_run',results:this.dataset==='smoke'?this.data():null,plan:this.plan,exported_at:new Date().toISOString()},null,2));this.h.toast('评估与数据来源已导出');break;}});}
}
